selector_to_html = {"a[href=\"#pyskyfire.ducts.pipe.Pipe.has_core\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.pipe.Pipe.has_core\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">has_core</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span></dt><dd><p>Whether a core runs along any of the pipe.</p></dd>", "a[href=\"#pyskyfire.ducts.pipe.Pipe.r_mean\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.pipe.Pipe.r_mean\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">r_mean</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.ndarray.html#numpy.ndarray\" title=\"(in NumPy v2.5)\"><span class=\"pre\">ndarray</span></a></span></dt><dd><p>Mean radius of the section, <code class=\"docutils literal notranslate\"><span class=\"pre\">(D</span> <span class=\"pre\">+</span> <span class=\"pre\">d)/4</span></code> [m], where swirl is measured.</p></dd>", "a[href=\"DuctResult.html#pyskyfire.ducts.pipe.DuctResult\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.pipe.DuctResult\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.pipe.</span></span><span class=\"sig-name descname\"><span class=\"pre\">DuctResult</span></span></dt><dd><p>Station states and per-interval diagnostics from a duct loss march.</p><p><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">Pipe.solve()</span></code> and <code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">solve()</span></code> both\nreturn one. <code class=\"docutils literal notranslate\"><span class=\"pre\">p_stagnation</span></code> is the marched pressure: the inlet pressure\nless the irreversible losses up to each station. It includes the swirl\u2019s\ndynamic head. The march is adiabatic, so <code class=\"docutils literal notranslate\"><span class=\"pre\">T_stagnation</span></code> is the inlet\ntemperature at every station, and <code class=\"docutils literal notranslate\"><span class=\"pre\">states</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">density</span></code> are evaluated\nat the two.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">meridional_velocity</span></code> is the through-flow velocity <code class=\"docutils literal notranslate\"><span class=\"pre\">c_m</span></code> normal to the\nflow area, <code class=\"docutils literal notranslate\"><span class=\"pre\">swirl_velocity</span></code> the circumferential <code class=\"docutils literal notranslate\"><span class=\"pre\">c_u</span></code> at the mean\nradius, and <code class=\"docutils literal notranslate\"><span class=\"pre\">velocity</span></code> their magnitude, which without swirl is the\nthrough-flow velocity. <code class=\"docutils literal notranslate\"><span class=\"pre\">T_static</span></code> is the stagnation temperature less\n<code class=\"docutils literal notranslate\"><span class=\"pre\">velocity**2/(2*cp)</span></code>, with <code class=\"docutils literal notranslate\"><span class=\"pre\">cp</span></code> taken at the same state as the\ndensity. Like <code class=\"docutils literal notranslate\"><span class=\"pre\">p_static</span></code> it is a first-order correction, not a\nstatic-state solution.</p><p>Per-interval arrays have one value fewer than the stations.\n<code class=\"docutils literal notranslate\"><span class=\"pre\">loss_coefficient</span></code> is referred to the through-flow head\n<code class=\"docutils literal notranslate\"><span class=\"pre\">rho*c_m**2/2</span></code> on the interval\u2019s mean section. <code class=\"docutils literal notranslate\"><span class=\"pre\">darcy_factor</span></code> is the\nfactor applied, including any curvature multiplier, and NaN over a lumped\nbend.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">stations</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">connections</span></code> are a <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Pipe</span></code>\u2019s resolved path, and\nNone for an <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">AnnularDuct</span></code>. <code class=\"docutils literal notranslate\"><span class=\"pre\">fluid</span></code> is the\nCoolProp name the transport carried, or None when it named none.</p></dd>", "a[href=\"#pyskyfire.ducts.pipe.Pipe.s\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.pipe.Pipe.s\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">s</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.ndarray.html#numpy.ndarray\" title=\"(in NumPy v2.5)\"><span class=\"pre\">ndarray</span></a></span></dt><dd><p>Arc length at each station [m].</p></dd>", "a[href=\"#pyskyfire.ducts.pipe.Pipe.hydraulic_diameter\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.pipe.Pipe.hydraulic_diameter\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">hydraulic_diameter</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.ndarray.html#numpy.ndarray\" title=\"(in NumPy v2.5)\"><span class=\"pre\">ndarray</span></a></span></dt><dd><p><code class=\"docutils literal notranslate\"><span class=\"pre\">4A/P</span></code> at each station, <code class=\"docutils literal notranslate\"><span class=\"pre\">D</span> <span class=\"pre\">-</span> <span class=\"pre\">d</span></code> [m]: the bore where there is no core.</p></dd>", "a[href=\"#pyskyfire.ducts.pipe.Pipe.solve\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.pipe.Pipe.solve\">\n<span class=\"sig-name descname\"><span class=\"pre\">solve</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_state</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"../../thermo/state/FluidState.html#pyskyfire.thermo.state.FluidState\" title=\"pyskyfire.thermo.state.FluidState\"><span class=\"pre\">FluidState</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mass_flow</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">transport</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_swirl</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">friction_model</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">'fluids'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">bend_length_scale</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">'hydraulic'</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"DuctResult.html#pyskyfire.ducts.pipe.DuctResult\" title=\"pyskyfire.ducts.pipe.DuctResult\"><span class=\"pre\">DuctResult</span></a></span></span></dt><dd><p>March irreversible pressure losses from inlet to outlet.</p><p><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Straight</span></code> and <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Continuous</span></code> connections charge wall\nfriction on the hydraulic diameter, the latter times the curvature\nmultiplier, along the helix a swirling flow follows, plus the loss of\nany change of area (<a class=\"reference internal\" href=\"#pyskyfire.ducts.pipe.Pipe.area_change_loss_coefficient\" title=\"pyskyfire.ducts.pipe.Pipe.area_change_loss_coefficient\"><code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">area_change_loss_coefficient</span></code></a>). A\n<code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">RoundedBend</span></code> charges its complete loss coefficient. Every loss\nis on the through-flow head <code class=\"docutils literal notranslate\"><span class=\"pre\">rho*c_m**2/2</span></code>. Acceleration and heat\ntransfer are intentionally absent: a change of area alters the\nvelocities, and so the static pressure, but adds no reversible term\nto the marched stagnation pressure.</p></dd>", "a[href=\"#pyskyfire-ducts-pipe-pipe\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts.pipe.Pipe<a class=\"headerlink\" href=\"#pyskyfire-ducts-pipe-pipe\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.ducts.pipe.Pipe.radius\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.pipe.Pipe.radius\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">radius</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.ndarray.html#numpy.ndarray\" title=\"(in NumPy v2.5)\"><span class=\"pre\">ndarray</span></a></span></dt><dd><p>Bore radius at each station [m].</p></dd>", "a[href=\"#pyskyfire.ducts.pipe.Pipe.core_radius\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.pipe.Pipe.core_radius\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">core_radius</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.ndarray.html#numpy.ndarray\" title=\"(in NumPy v2.5)\"><span class=\"pre\">ndarray</span></a></span></dt><dd><p>Core radius at each station [m], zero where there is no core.</p></dd>", "a[href=\"#pyskyfire.ducts.pipe.Pipe\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.pipe.Pipe\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.pipe.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Pipe</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">path</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">connections</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">diameter</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">core_diameter</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roughness</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">Callable</span><span class=\"p\"><span class=\"pre\">[</span></span><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"p\"><span class=\"pre\">]</span></span><span class=\"p\"><span class=\"pre\">,</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"p\"><span class=\"pre\">]</span></span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">max_diameter_change</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">0.02</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A circular duct swept along a path, with an optional core, and its loss solver.</p><p>The section normal to the path is a circular bore of <code class=\"docutils literal notranslate\"><span class=\"pre\">diameter</span></code>, with a\nconcentric core of <code class=\"docutils literal notranslate\"><span class=\"pre\">core_diameter</span></code> inside it where that is not zero. A\nplain pipe has no core. A core may run the whole length, as in coaxial\nlines, or only part of it: it may start from a point, as a turbine\u2019s nose\ndoes, and end, bluntly or tapering.</p><p>The march evaluates each connection at one section, the mean of its two\nends. Where the section varies, the pipe therefore splits\n<code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Straight</span></code> and <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Continuous</span></code> connections itself until its\narea and hydraulic diameter each change by at most\n<code class=\"docutils literal notranslate\"><span class=\"pre\">max_diameter_change</span></code> (relative, the area as the diameter of the circle\nof the same area) across each piece, placing the extra stations where the\nsection changes fastest. A constant section is left exactly as supplied,\nand so is every <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">RoundedBend</span></code>. <code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">path</span></code>, <code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">stations</span></code> and\nevery result refer to the resolved stations, which include all of the\nsupplied ones.</p></dd>", "a[href=\"DisplayPath.html#pyskyfire.ducts.pipe.DisplayPath\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.pipe.DisplayPath\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.pipe.</span></span><span class=\"sig-name descname\"><span class=\"pre\">DisplayPath</span></span></dt><dd><p>A refined centerline for drawing, never for pressure-loss marching.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">points</span></code> [m] and <code class=\"docutils literal notranslate\"><span class=\"pre\">radius</span></code> [m] describe the swept circular bore, and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">core_radius</span></code> [m] the core inside it, zero where there is none. The\npath carries its own provenance so results can follow it: <code class=\"docutils literal notranslate\"><span class=\"pre\">station</span></code> is\nthe fractional <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">PathStation</span></code> index of every point, and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">connection</span></code> is the originating connection index of every segment\nbetween consecutive points.</p></dd>", "a[href=\"#pyskyfire.ducts.pipe.Pipe.cone_angle\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.pipe.Pipe.cone_angle\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">cone_angle</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.ndarray.html#numpy.ndarray\" title=\"(in NumPy v2.5)\"><span class=\"pre\">ndarray</span></a></span></dt><dd><p>Full cone angle of each connection [rad], positive where the area grows.</p><p>The angle of the cone whose area grows as the section\u2019s does, from\nthe diameter <code class=\"docutils literal notranslate\"><span class=\"pre\">sqrt(4A/pi)</span></code> at the connection\u2019s ends over its length\nalong the centerline. For a pipe without a core it is the bore\u2019s own\nwall angle. It is local wherever <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Pipe</span></code> has split a varying\nsection; with <code class=\"docutils literal notranslate\"><span class=\"pre\">max_diameter_change=math.inf</span></code> it only sees the\nsupplied stations.</p></dd>", "a[href=\"../../thermo/state/FluidState.html#pyskyfire.thermo.state.FluidState\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.state.FluidState\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.state.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FluidState</span></span></dt><dd><p>Resolved bulk fluid state at one axial station.</p></dd>", "a[href=\"#pyskyfire.ducts.pipe.Pipe.area_change_loss_coefficient\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.pipe.Pipe.area_change_loss_coefficient\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">area_change_loss_coefficient</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.ndarray.html#numpy.ndarray\" title=\"(in NumPy v2.5)\"><span class=\"pre\">ndarray</span></a></span></dt><dd><p>Loss coefficient of each connection for its change of area [-].</p><p>Where the flow area keeps growing, the flow loses to its slowing as a\ndiffuser does, and where it keeps shrinking, to its speeding up as a\ncontraction does. <a class=\"reference internal\" href=\"#pyskyfire.ducts.pipe.Pipe.solve\" title=\"pyskyfire.ducts.pipe.Pipe.solve\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">solve()</span></code></a> adds this to each connection\u2019s wall\nfriction. A run of connections changing area the same way is one\ndiffuser or contraction: it ends where the area changes the other way,\nor at a constant-section stretch longer than four hydraulic\ndiameters. Each run loses Rennels\u2019 conical-diffuser or\nconical-contraction term for its end sections, at the cone angle\naveraged over the run, weighted by where the flow slows or speeds up.\nThat is his value for a true cone and for a step alike, and it is\nunchanged by how finely the pipe is split or by a nearly parallel\nstretch at either end. The run\u2019s loss is shared out in the same\nproportion. Coefficients are on each connection\u2019s through-flow head\nat its mean section; zero where the area is constant.</p></dd>", "a[href=\"#pyskyfire.ducts.pipe.Pipe.display_path\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.pipe.Pipe.display_path\">\n<span class=\"sig-name descname\"><span class=\"pre\">display_path</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">segments</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#int\" title=\"(in Python v3.15)\"><span class=\"pre\">int</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">16</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"DisplayPath.html#pyskyfire.ducts.pipe.DisplayPath\" title=\"pyskyfire.ducts.pipe.DisplayPath\"><span class=\"pre\">DisplayPath</span></a></span></span></dt><dd><p>Resolve renderable geometry, opening arc connections into their arcs.</p><p>A <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">RoundedBend</span></code> is one connection between tangent points, and a\ngenerated <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Continuous</span></code> arc may be one connection too, so\n<a class=\"reference internal\" href=\"#pyskyfire.ducts.pipe.Pipe.centerline\" title=\"pyskyfire.ducts.pipe.Pipe.centerline\"><code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">centerline</span></code></a> crosses such a corner as a chord. Here every arc\nconnection with a resolved <code class=\"docutils literal notranslate\"><span class=\"pre\">center</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">normal</span></code> is redrawn as an\narc of <code class=\"docutils literal notranslate\"><span class=\"pre\">segments</span></code> sides per quarter turn, at least one. A connection\nwithout that geometry keeps its chord, because its plane is not\nrecoverable from the loss model alone.</p><p>This changes drawn shape only. Lengths, losses, and every solver\nquantity come from the stations and connections, which are unchanged.</p></dd>", "a[href=\"#pyskyfire.ducts.pipe.Pipe.centerline\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.pipe.Pipe.centerline\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">centerline</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.ndarray.html#numpy.ndarray\" title=\"(in NumPy v2.5)\"><span class=\"pre\">ndarray</span></a></span></dt><dd><p>Resolved station positions with shape <code class=\"docutils literal notranslate\"><span class=\"pre\">(N,</span> <span class=\"pre\">3)</span></code> [m].</p></dd>", "a[href=\"#pyskyfire.ducts.pipe.Pipe.area\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.pipe.Pipe.area\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">area</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.ndarray.html#numpy.ndarray\" title=\"(in NumPy v2.5)\"><span class=\"pre\">ndarray</span></a></span></dt><dd><p>Flow area at each station [m\u00b2].</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
